{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In healthy subjects, oral pentosan polysulfate sodium had an absolute bioavailability of only 0.5-1% versus i.v. dosing, directly demonstrating that a highly sulfated, polar molecule is far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Dextran sulfate, another sulfated polysaccharide, is reported to have poor oral bioavailability in humans, supporting the expectation that sulfate-rich, highly polar molecules are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The clinical absolute bioavailability of INVIRASE (saquinavir) is 4% (range 1-9%) in humans, providing an example of a real oral drug with measurable but clearly sub-20% absolute bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Puerarin, a polar glycoside-like molecule, exhibits low oral bioavailability in animals and humans, supporting low F for compounds with high polarity and poor membrane permeability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query molecule is extremely polar, highly ionized, and contains sulfate and carboxylic acid groups, predicting negligible passive permeability. Direct human evidence from structurally related sulfated molecules (pentosan polysulfate, dextran sulfate) shows very low oral bioavailability, and other low-bioavailability comparators are all below 20%. Therefore, the prediction is low oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the exact query molecule.",
    "The query is likely a smaller sulfated disaccharide-like molecule, whereas the strongest evidence comes from larger sulfated polysaccharides; size differences may affect absorption mechanisms but not the expected direction.",
    "No evidence addresses possible active transport or carrier-mediated absorption for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

